{"implementation":"def solve(case):
    nodes = case["nodes"]
    required = set(case["required_symbols"])
    by_id = {node["id"]: node for node in nodes}
    retained = {node["id"] for node in nodes if not node["removable"]}

    present = {by_id[node_id]["symbol"] for node_id in retained}
    for symbol in required - present:
        candidates = [node for node in nodes if node["symbol"] == symbol]
        if candidates:
            best = max(candidates, key=lambda node: node["utility"])
            retained.add(best["id"])

    pending = list(retained)
    while pending:
        node_id = pending.pop()
        parent = by_id[node_id]["parent"]
        if parent is not None and parent not in retained:
            retained.add(parent)
            pending.append(parent)

    return {
        "removed_node_ids": [node["id"] for node in nodes if node["id"] not in retained],
        "retained_node_ids": [node["id"] for node in nodes if node["id"] in retained],
    }
"}
